// Gyroid
// Approximates the Gyroid isosurface
// f(x,y,z) = sin(x)cos(y) + sin(y)cos(z) + sin(z)cos(x)
// by sampling a 3D grid and drawing line segments
// at zero-crossings between neighboring grid points.

const GRID_RES = 60;
const TOTAL_SIZE = 600;
const STEP = TOTAL_SIZE / GRID_RES;
const LIMIT = 0.25;

let gyroidModel;

function gyroid(x, y, z) {
  return sin(x) * cos(y) + sin(y) * cos(z) + sin(z) * cos(x);
}

function zeroCross(v1, v2) {
  return (v1 > 0 && v2 <= 0) || (v1 < 0 && v2 >= 0);
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  perspective(PI / 3, width / height, 0.1, 10000);

  const delta = (TWO_PI / TOTAL_SIZE) * STEP;

  gyroidModel = buildGeometry(() => {
    for (let i = 0; i < GRID_RES; i++) {
      for (let j = 0; j < GRID_RES; j++) {
        for (let k = 0; k < GRID_RES; k++) {
          // Physical coordinates for rendering
          const px = -TOTAL_SIZE / 2 + i * STEP;
          const py = -TOTAL_SIZE / 2 + j * STEP;
          const pz = -TOTAL_SIZE / 2 + k * STEP;

          // Normalized coordinates for the gyroid function (-PI to PI)
          const x = map(px, -TOTAL_SIZE / 2, TOTAL_SIZE / 2, -PI, PI);
          const y = map(py, -TOTAL_SIZE / 2, TOTAL_SIZE / 2, -PI, PI);
          const z = map(pz, -TOTAL_SIZE / 2, TOTAL_SIZE / 2, -PI, PI);

          const val = gyroid(x, y, z);

          if (abs(val) > LIMIT) continue;

          if (zeroCross(val, gyroid(x + delta, y, z))) {
            line(px, py, pz, px + STEP, py, pz);
          }
          if (zeroCross(val, gyroid(x, y + delta, z))) {
            line(px, py, pz, px, py + STEP, pz);
          }
          if (zeroCross(val, gyroid(x, y, z + delta))) {
            line(px, py, pz, px, py, pz + STEP);
          }
        }
      }
    }
  });
}

function draw() {
  background(0);
  orbitControl();
  rotateY(frameCount * 0.002);

  stroke(255);
  strokeWeight(1);
  noFill();

  model(gyroidModel);
}
